#include <bits/stdc++.h>
using namespace std;

typedef pair<int,int> par;

const int MAXR = 11;
const int MAXN = 1000;
const int MAXM = 100100;
const int INF = (1<<29);

int edges[2*MAXM], flows[2*MAXM], capacities[2*MAXM], nextEdge[2*MAXM];
int head[MAXN], current[MAXN], level[MAXN], queueArr[MAXN];
int edgeCount, totalNodes, source, sink, front, rear;

void initializeFlow(int nodes, int sNode, int tNode) {
    totalNodes = nodes; source = sNode; sink = tNode; edgeCount = 2;
    for (int i=0; i<=totalNodes; i++) head[i] = 0;
}
void addFlowEdge(int u, int v, int capVal) {
    edges[edgeCount] = v; flows[edgeCount] = 0; capacities[edgeCount] = capVal; nextEdge[edgeCount] = head[u]; head[u] = edgeCount++;
    edges[edgeCount] = u; flows[edgeCount] = 0; capacities[edgeCount] = 0; nextEdge[edgeCount] = head[v]; head[v] = edgeCount++;
}
bool buildLevelGraph() {
    for (int i=0; i<=totalNodes; i++) level[i] = 0;
    front = rear = 0;
    queueArr[front++] = source;
    level[source] = 1;
    while (rear < front && !level[sink]) {
        int u = queueArr[rear++];
        for (int e = head[u]; e; e = nextEdge[e]) {
            int v = edges[e];
            if (!level[v] && flows[e] < capacities[e]) {
                level[v] = level[u] + 1;
                queueArr[front++] = v;
            }
        }
    }
    return level[sink] != 0;
}
int sendFlow(int u, int flowAmount) {
    if (u == sink) return flowAmount;
    for (int &e = current[u], f=0; e; e= current[u]=nextEdge[e]) {
        int v = edges[e];
        if (level[u] < level[v] && flows[e] < capacities[e] && (f=sendFlow(v, min(flowAmount, capacities[e]-flows[e])))) {
            flows[e] += f;
            flows[e^1] -= f;
            return f;
        }
    }
    return 0;
}
int maxFlow() {
    int totalFlow=0, flowVal;
    while (buildLevelGraph()) {
        for (int i=0; i<=totalNodes; i++) current[i] = head[i];
        while ((flowVal=sendFlow(source, INF))) totalFlow += flowVal;
    }
    return totalFlow;
}

int R;
string grid1[MAXR], grid2[MAXR];

int deltaI[] = {0,1,0,-1};
int deltaJ[] = {1,0,-1,0};

bool canTraverse(int i, int j) {
    return (i>=0 && j>=0 && i<R && j<R && grid1[i][j]!='Y' && grid1[i][j]!='Z');
}

int timeMap[2][MAXR][MAXR];

void performBFS(int i, int j, int c) {
    for (int k=0; k<R; k++) {
        for (int l=0; l<R; l++) {
            timeMap[c][k][l]=0;
        }
    }
    timeMap[c][i][j]=1;
    queue<par> q;
    q.push({i,j});
    while (!q.empty()) {
        auto [x,y]=q.front(); q.pop();
        if (c==1 && (timeMap[0][x][y] && timeMap[0][x][y]<=timeMap[1][x][y])) continue;
        for (int k=0; k<4; k++) {
            int ni=x+deltaI[k], nj=y+deltaJ[k];
            if (canTraverse(ni,nj) && !timeMap[c][ni][nj]) {
                timeMap[c][ni][nj]=timeMap[c][x][y]+1;
                q.push({ni,nj});
            }
        }
    }
}

int nodeID[2][MAXR][MAXR];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int T; cin >> R >> T;
    int zi=0, zj=0;
    int totalNodes=0, start=0, end=0;
    for (int i=0; i<R; i++) {
        cin >> grid1[i];
        for (int j=0; j<R; j++) {
            if (grid1[i][j]=='Z') {
                zi=i; zj=j;
            } else if (grid1[i][j]!='Y') {
                totalNodes++;
                nodeID[0][i][j]=totalNodes;
            }
        }
    }
    for (int i=0; i<R; i++) {
        cin >> grid2[i];
        for (int j=0; j<R; j++) {
            if (grid2[i][j]!='Y' && grid2[i][j]!='Z') {
                totalNodes++;
                nodeID[1][i][j]=totalNodes;
            }
        }
    }
    totalNodes++;
    start=0; end=totalNodes;
    initializeFlow(totalNodes, start, end);
    for (int i=0; i<R; i++) {
        for (int j=0; j<R; j++) {
            if (grid1[i][j]!='Z' && grid1[i][j]!='Y') {
                addFlowEdge(start, nodeID[0][i][j], grid1[i][j]-'0');
                addFlowEdge(nodeID[1][i][j], end, grid2[i][j]-'0');
            }
        }
    }
    performBFS(zi, zj, 0);
    for (int i=0; i<R; i++) {
        for (int j=0; j<R; j++) {
            if (grid1[i][j]>'0' && grid1[i][j]<='9') {
                performBFS(i, j, 1);
                for (int ii=0; ii<R; ii++) {
                    for (int jj=0; jj<R; jj++) {
                        if (grid2[ii][jj]>'0' && grid2[ii][jj]<='9') {
                            if (timeMap[1][ii][jj] && (!timeMap[0][ii][jj] || timeMap[0][ii][jj]>=timeMap[1][ii][jj]) && timeMap[1][ii][jj]-1<=T) {
                                addFlowEdge(nodeID[0][i][j], nodeID[1][ii][jj], INF);
                            }
                        }
                    }
                }
            }
        }
    }
    cout << maxFlow() << '\n';
}
